      "classification": "vulnerability",
      "code_path": "beacon_node/beacon_chain/src/data_column_verification.rs::verify_data_column_sidecar::L532-561",
      "proof_trace": "Validation exists but is only enforced on gossip path (L480). RPC paths (DataColumnsByRoot/ByRange at lighthouse_network/src/rpc/codec.rs:696,717) and database loads (store/src/hot_cold_store.rs:2529,3252) bypass the guard, allowing mismatched array lengths.",
      "attack_scenario": "Malicious peer sends RPC response with column.len()\u2260kzg_commitments.len()\u2260kzg_proofs.len(). Deserialization succeeds, validation is skipped, KZG verification accesses wrong indices causing out-of-bounds panic or incorrect proof validation.",
      "checklist_id": "PROP-6a4369e9-inv-010"
    },
    "text": "Column, kzg_commitments, and kzg_proofs arrays must all have equal length.",
    "assertion": "forall sidecar: len(sidecar.column) == len(sidecar.kzg_commitments) == len(sidecar.kzg_proofs)",
    "covers": "SG-002",
    "severity": "HIGH",
    "type": "invariant"
  }
}

